    --cellSize:118px; /* results in ~4*(118)+5*16 = 600px board */
    --radius:10px;
    --brown:#a7866a;
    --brownText:#fff;
  }
  *{box-sizing:border-box}
  html,body{height:100%}
  body{
    margin:0;
    background:var(--bg);
    color:var(--text);
    font-family: system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;
  }
  .wrap{
    width: 900px;
    margin: 0 auto;
    padding: 30px 20px 80px;
