    font-weight:900;
  }
  .topbar{
    width: 640px;
    margin: 0 auto 14px;
    display:flex;
    align-items:center;
    justify-content:space-between;
  }
  .scoreBox{
    display:flex;
    gap:10px;
  }
  .score{
    background:#b4987e;
