    font-weight:700;
  }
  /* Board */
  .boardWrap{
    display:grid;
    place-items:center;
  }
  .board{
    position:relative;
    width: calc(var(--cellSize) * 4 + var(--gap) * 5);
    height: calc(var(--cellSize) * 4 + var(--gap) * 5);
    background: var(--board);
    border-radius: 12px;
    padding: var(--gap);
    box-shadow: inset 0 4px 0 rgba(0,0,0,.05);
  }
  .grid{
    position:absolute;
    inset:0;
    padding:var(--gap);
    display:grid;
    grid-template-columns: repeat(4, var(--cellSize));
    grid-template-rows: repeat(4, var(--cellSize));
    gap:var(--gap);
  }
  .grid .cell{
    background:var(--cell);
    border-radius:8px;
  }
  .tiles{
    position:absolute;
    inset:0;
    padding:var(--gap);
    display:grid;
    grid-template-columns: repeat(4, var(--cellSize));
    grid-template-rows: repeat(4, var(--cellSize));
    gap:var(--gap);
  }
  .tile{
    display:flex;
    align-items:center;
    justify-content:center;
    border-radius:8px;
    font-weight:900;
    color:#776e65;
    background:#eee4da;
    user-select:none;
  }
  .tile[data-v="2"]{ background:#eee4da; color:#776e65;}
  .tile[data-v="4"]{ background:#ede0c8; color:#776e65;}
  .tile[data-v="8"]{ background:#f2b179; color:#f9f6f2;}
  .tile[data-v="16"]{ background:#f59563; color:#f9f6f2;}
  .tile[data-v="32"]{ background:#f67c5f; color:#f9f6f2;}
  .tile[data-v="64"]{ background:#f65e3b; color:#f9f6f2;}
  .tile[data-v="128"]{ background:#edcf72; color:#f9f6f2;}
  .tile[data-v="256"]{ background:#edcc61; color:#f9f6f2;}
  .tile[data-v="512"]{ background:#edc850; color:#f9f6f2;}
  .tile[data-v="1024"]{ background:#edc53f; color:#f9f6f2;}
  .tile[data-v="2048"]{ background:#edc22e; color:#f9f6f2;}
  .tile.appear{
    animation: pop .16s ease-out;
  }
  @keyframes pop{
    from{transform:scale(.7); opacity:.2}
    to{transform:scale(1); opacity:1}
  }
  .note{
    max-width:980px;
    margin: 24px auto 0;
    background:#f4debb;
    color:#7b5d45;
    padding:18px 20px;
    border-radius: 8px;
    font-size:15px;
  }
  .ad{
    margin: 18px auto 4px;
  }
  .ad img{
    border-radius:6px;
    border:1px solid rgba(0,0,0,.08);
  }
  .overlay{
    position:absolute;
    inset:0;
    display:none;
    align-items:center;
    justify-content:center;
    background: rgba(255,255,255,.8);
    border-radius:12px;
  }
  .overlay.show{display:flex;}
  .overlay .panel{
    background:white;
    border-radius:10px;
    padding:18px 22px;
    box-shadow: 0 12px 30px rgba(0,0,0,.15);
    text-align:center;
  }
  .overlay h3{margin:0 0 8px; font-size:26px}
  .overlay .panel .actions{
    margin-top:10px;
    display:flex;
    gap:10px;
    justify-content:center;
  }
  .games{
    margin-top:34px;
    padding-top:24px;
    border-top:1px solid rgba(0,0,0,.08);
  }
  .games h2{
    font-size:28px;
    margin:0 0 16px;
  }
  .cards{
    display:flex;
    gap:16px;
    overflow:auto;
    padding-bottom:8px;
  }
  .card{
    background:#fff;
    border-radius:12px;
    width:260px;
    flex: 0 0 260px;
    box-shadow: 0 6px 16px rgba(0,0,0,.08);
    padding:12px;
    text-align:center;
  }
  .card img{
    max-width:100%;
    border-radius:10px;
    display:block;
    margin:0 auto 10px;
  }
  .card .title{font-weight:700; margin-bottom:6px}
  .card .play.btn{
    background:#3a86ff;
    color:#fff;
    border:none;
    padding:10px 12px;
    border-radius:8px;
    font-weight:700;
  }
  /* Helpers for buttons focus */
  .btn:focus{outline:2px solid #0000; outline-offset:2px}
</style>
</head>
<body>
  <div class="wrap">
    <div class="modes">
      <div class="pill active btn" id="modeClassic">Classic</div>
      <div class="pill btn" id="modeCupcakes">Cupcakes</div>
    </div>
    <h1>2048 Game</h1>

    <div class="topbar">
      <div class="scoreBox">
        <div class="score">
          <div class="label">SCORE</div>
          <div class="value" id="score">0</div>
        </div>
        <div class="score">
          <div class="label">BEST</div>
          <div class="value" id="best">0</div>
        </div>
      </div>
      <button class="newgame btn" id="newGameBtn">New game</button>
    </div>

    <div class="boardWrap">
      <div class="board" id="board" tabindex="0" aria-label="2048 board. Use arrow keys to move">
        <div class="overlay" id="overlay">
          <div class="panel">
            <h3 id="overlayTitle">Game Over</h3>
            <div>Try again to beat your best score.</div>
            <div class="actions">
              <button class="newgame btn" id="overlayNew">New game</button>
            </div>
          </div>
        </div>
        <div class="grid" aria-hidden="true">
          <div class="cell"></div><div class="cell"></div><div class="cell"></div><div class="cell"></div>
          <div class="cell"></div><div class="cell"></div><div class="cell"></div><div class="cell"></div>
          <div class="cell"></div><div class="cell"></div><div class="cell"></div><div class="cell"></div>
          <div class="cell"></div><div class="cell"></div><div class="cell"></div><div class="cell"></div>
        </div>
        <div class="tiles" id="tiles"></div>
      </div>

      <div class="ad">
        <img src="__PLACEHOLDER_ASSETS_BASE_DIR__/015.png" width="420" height="280" alt="Sponsored" />
      </div>
    </div>

    <div class="note">
      Use your arrow keys (also W, A, S, and D keys alternatively) or swipe on touch devices to move the tiles. When two tiles with the same number touch, they merge into one. Try to get the 2048 tile!
    </div>

    <div class="games">
      <h2>Play Other Games</h2>
      <div class="cards">
