          <img src="__PLACEHOLDER_ASSETS_BASE_DIR__/013.png" width="480" height="320" alt="Flap">
          <div class="title">Birdy</div>
          <button class="play btn">Play</button>
        </div>
      </div>
    </div>
  </div>

<script>
(function(){
  const size = 4;
  let board = [];
  let score = 0;
  let best = Number(localStorage.getItem('best2048')||0);
  const tilesWrap = document.getElementById('tiles');
  const scoreEl = document.getElementById('score');
  const bestEl = document.getElementById('best');
  const overlay = document.getElementById('overlay');
  const boardEl = document.getElementById('board');

  bestEl.textContent = best;

  function emptyBoard(){
    board = new Array(size).fill(0).map(()=>new Array(size).fill(0));
  }

  function randomEmptyCell(){
    const empties = [];
    for(let r=0;r<size;r++){
      for(let c=0;c<size;c++){
        if(board[r][c]===0) empties.push([r,c]);
      }
    }
    if(empties.length===0) return null;
    return empties[Math.floor(Math.random()*empties.length)];
  }

  function spawn(n=1){
    for(let i=0;i<n;i++){
      const cell = randomEmptyCell();
      if(!cell) return;
      const [r,c]=cell;
      board[r][c] = Math.random()<0.9?2:4;
    }
  }

  function render(){
    tilesWrap.innerHTML = '';
    for(let r=0;r<size;r++){
      for(let c=0;c<size;c++){
        const v = board[r][c];
        const tile = document.createElement('div');
        tile.className = 'tile';
        if(v===0){
          tile.style.visibility='hidden';
        }else{
          tile.dataset.v = v;
          tile.textContent = v;
          tile.style.fontSize = (v>=1024?32:v>=128?36:v>=16?44:54)+'px';
          tile.classList.add('appear');
        }
        tilesWrap.appendChild(tile);
      }
    }
    scoreEl.textContent = score;
    bestEl.textContent = best;
  }

  function transpose(m){
    return m[0].map((_,i)=>m.map(row=>row[i]));
  }
  function reverseRows(m){
    return m.map(row=>row.slice().reverse());
  }

  function slideRowLeft(row){
    const nonZero = row.filter(v=>v!==0);
    let moved=false;
    for(let i=0;i<nonZero.length-1;i++){
      if(nonZero[i]===nonZero[i+1]){
        nonZero[i]*=2;
        score+=nonZero[i];
        nonZero[i+1]=0;
        moved=true;
      }
    }
    const compact = nonZero.filter(v=>v!==0);
    while(compact.length<row.length) compact.push(0);
    // detect movement
    for(let i=0;i<row.length;i++){
      if(row[i]!==compact[i]) moved=true;
    }
    return {row:compact, moved};
  }

  function move(dir){
    // dir: 'left','right','up','down'
    let moved=false;
    let m = board.map(r=>r.slice());
    if(dir==='right'){
      m = reverseRows(m);
    }else if(dir==='up'){
      m = transpose(m);
    }else if(dir==='down'){
      m = transpose(m);
      m = reverseRows(m);
    }
    let newM=[];
    for(const r of m){
      const res = slideRowLeft(r);
      newM.push(res.row);
      if(res.moved) moved = true;
    }
    if(dir==='right'){
      newM = reverseRows(newM);
    }else if(dir==='up'){
      newM = transpose(newM);
    }else if(dir==='down'){
      newM = reverseRows(newM);
      newM = transpose(newM);
    }
    if(moved){
      board = newM;
      spawn(1);
      if(score>best){ best=score; localStorage.setItem('best2048',best); }
      render();
      checkState();
    }
  }

  function anyMovesLeft(){
    // empty cell
    for(let r=0;r<size;r++){
      for(let c=0;c<size;c++){
        if(board[r][c]===0) return true;
      }
    }
    // adjacent equal
    for(let r=0;r<size;r++){
      for(let c=0;c<size;c++){
        const v=board[r][c];
        if(r+1<size && board[r+1][c]===v) return true;
        if(c+1<size && board[r][c+1]===v) return true;
      }
    }
    return false;
  }

  function checkState(){
    for(let r=0;r<size;r++){
      for(let c=0;c<size;c++){
        if(board[r][c]===2048){
          showOverlay('You win!');
          return;
        }
      }
    }
    if(!anyMovesLeft()){
      showOverlay('Game Over');
    }
  }

  function showOverlay(text){
    document.getElementById('overlayTitle').textContent = text;
    overlay.classList.add('show');
  }

  function newGame(){
    score = 0;
    overlay.classList.remove('show');
    emptyBoard();
    spawn(2);
    render();
  }

  // Keyboard
  window.addEventListener('keydown',(e)=>{
    const k = e.key.toLowerCase();
    const block = ['arrowleft','arrowright','arrowup','arrowdown','a','d','w','s'];
    if(!block.includes(k)) return;
    e.preventDefault();
    const map={
      'arrowleft':'left','a':'left',
      'arrowright':'right','d':'right',
      'arrowup':'up','w':'up',
      'arrowdown':'down','s':'down'
    };
    move(map[k]);
  },{passive:false});

  // Touch swipe
  let startX=0,startY=0;
  boardEl.addEventListener('touchstart',e=>{
    const t=e.changedTouches[0];
    startX=t.clientX; startY=t.clientY;
  },{passive:true});
  boardEl.addEventListener('touchend',e=>{
    const t=e.changedTouches[0];
    const dx=t.clientX-startX, dy=t.clientY-startY;
    if(Math.max(Math.abs(dx),Math.abs(dy))<24) return;
    if(Math.abs(dx)>Math.abs(dy)) move(dx>0?'right':'left');
    else move(dy>0?'down':'up');
  });

  // Buttons
  document.getElementById('newGameBtn').addEventListener('click', newGame);
  document.getElementById('overlayNew').addEventListener('click', newGame);

  // Mode toggles (visual only)
  const classicBtn = document.getElementById('modeClassic');
  const cupcakeBtn = document.getElementById('modeCupcakes');
  classicBtn.addEventListener('click', ()=>{
    classicBtn.classList.add('active');
    cupcakeBtn.classList.remove('active');
    document.documentElement.style.setProperty('--board','#bbada0');
    document.documentElement.style.setProperty('--cell','#cdc1b4');
  });
  cupcakeBtn.addEventListener('click', ()=>{
    cupcakeBtn.classList.add('active');
    classicBtn.classList.remove('active');
    // playful pastel palette (visual only)
    document.documentElement.style.setProperty('--board','#c9b1e0');
    document.documentElement.style.setProperty('--cell','#e8ddf4');
  });

  // Init
  newGame();
})();
</script>
</body>
</html>
